<?php
require_once __DIR__ . '/../config/database.php'; require_login(); $user = current_user(); $query = db()->prepare('SELECT r.* FROM recommendations r JOIN students s ON s.id = r.student_id WHERE s.user_id = ? ORDER BY r.created_at DESC'); $query->execute([$user['id']]); $history = $query->fetchAll(); $title = 'Recommendation history'; require __DIR__ . '/../includes/header.php'; ?><div class="container py-5"><div class="eyebrow">Your record</div><h1 class="section-title mb-4">Recommendation history.</h1><div class="panel table-responsive"><table class="table align-middle"><thead><tr><th>Created</th><th>Primary tendency</th><th>Confidence</th><th>Student score</th></tr></thead><tbody><?php foreach ($history as $item): ?><tr><td><?= e($item['created_at']) ?></td><td><?= e($item['predicted_interest']) ?></td><td><?= round((float)$item['confidence'] * 100, 1) ?>%</td><td><?= e((string)$item['student_score']) ?></td></tr><?php endforeach; ?></tbody></table><?php if (!$history): ?><p class="text-muted mb-0">Generate your first recommendation to see it here.</p><?php endif; ?></div></div><?php require __DIR__ . '/../includes/footer.php'; ?>